INSERT INTO test_questions (id, test_id, question_text, audio_url, options, correct_answer, points, order_index, created_at) VALUES ('358b5a91-88eb-4481-9334-e5853bdccda5', '907602a7-d59c-4ad7-bebd-96d3e95bcf7c', '### Vente de véhicule d''occasion

