INSERT INTO test_questions (id, test_id, question_text, audio_url, options, correct_answer, points, order_index, created_at) VALUES ('24558ed4-b306-4509-b5f4-98071e9b9749', '907602a7-d59c-4ad7-bebd-96d3e95bcf7c', '### L''impact de la 5G sur l''industrie manufacturière

Le déploiement de la 5G ne se limite pas à une augmentation de la vitesse pour les smartphones. Dans le secteur manufacturier, cette technologie permet l''avènement de ''l''usine intelligente''. Grâce à une latence extrêmement faible, les capteurs installés sur les chaînes de montage peuvent communiquer en temps réel avec des algorithmes d''IA pour prédire les pannes avant qu''elles ne surviennent. Cette maintenance prédictive réduit considérablement les temps d''arrêt et optimise la consommation énergétique. Néanmoins, l''adoption de la 5G nécessite des investissements massifs en infrastructure et une formation poussée des techniciens pour manipuler ces nouveaux outils numériques de haute précision.

Question : Quel est le principal avantage de la 5G pour les usines ?', NULL, '["Appeler les clients plus vite", "La communication en temps réel des capteurs", "Remplacer tous les ouvriers par des robots", "Baisser les salaires"]', 'La communication en temps réel des capteurs', 1, 33, '2026-07-18T04:14:18.091031');
INSERT INTO test_questions (id, test_id, question_text, audio_url, options, correct_answer, points, order_index, created_at) VALUES ('3c105bde-12d4-4aed-8752-99e56e27a1de', '907602a7-d59c-4ad7-bebd-96d3e95bcf7c', '### L''impact de la 5G sur l''industrie manufacturière

